struct Parser {
  std::vector<Token> toks; std::size_t pos = 0;
  const Token& peek(std::size_t k = 0) const { return toks[pos + k]; }
  NodePtr parseTerm();                        // one member per grammar rule
  NodePtr parseExpr() {
    auto left = parseTerm();
    while (peek().kind == Tok::Plus || peek().kind == Tok::Minus)  // loop, not left recursion
      left = makeBinary(consume().kind, std::move(left), parseTerm());
    return left;
  }
};

